"""Phase 2.4 — page intégrée de gestion des catégories.
Réutilise exclusivement les API isolées déjà validées : diagnostic, ajout, renommage, suppression sécurisée.
"""
from flask import Response


def register_category_admin_phase24(app, db):
 @app.get('/administration/categories')
 def category_admin_phase24_page():
  return Response(r'''<!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>BÉCHÉFAA • Catégories</title><style>*{box-sizing:border-box}body{margin:0;font-family:Arial;background:#f4f5f7;color:#17191c}.top{background:#111827;color:#fff;padding:15px 22px}.top a{color:#fff;margin-left:18px}.wrap{max-width:1050px;margin:auto;padding:24px}.card{background:#fff;border-radius:14px;padding:18px;margin:14px 0}h1{margin-bottom:6px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:14px}label{display:block;font-weight:700;margin-top:8px}input{width:100%;padding:11px;margin:6px 0 10px;border:1px solid #ccd1d8;border-radius:8px}button{border:0;border-radius:8px;padding:11px 15px;background:#111827;color:#fff;font-weight:700;cursor:pointer}.danger{background:#b42318}.hint{color:#667085;font-size:13px}.msg{margin-top:10px;padding:10px;border-radius:8px}.ok{background:#e8f7ee}.err{background:#fff0ee;color:#9d261d}table{width:100%;border-collapse:collapse}th,td{text-align:left;padding:9px;border-bottom:1px solid #eee}@media(max-width:760px){.grid{grid-template-columns:1fr}}</style></head><body><div class="top"><b>BÉCHÉFAA • Administration</b><a href="/administration/produits">Produits</a><a href="/administration/options-produits">Options</a><a href="/pos">Caisse</a></div><div class="wrap"><h1>Gestion des catégories</h1><p class="hint">Création, renommage et suppression sécurisée. Une catégorie contenant un produit ne peut pas être supprimée.</p><div id="summary"></div><div class="card"><h2>Catégories actuelles</h2><table><thead><tr><th>Catégorie</th><th>Produits</th><th>Actifs</th></tr></thead><tbody id="rows"></tbody></table></div><div class="grid"><div class="card"><h2>Ajouter</h2><label>Nouvelle catégorie</label><input id="add"><button onclick="addCat()">Ajouter en fin de liste</button><div id="addmsg"></div></div><div class="card"><h2>Renommer</h2><label>Nom actuel</label><input id="old"><label>Nouveau nom</label><input id="new"><button onclick="renameCat()">Renommer</button><div id="renmsg"></div></div></div><div class="card"><h2>Supprimer</h2><p class="hint">Suppression autorisée uniquement si aucun produit n'utilise la catégorie.</p><label>Catégorie vide</label><input id="del"><button class="danger" onclick="deleteCat()">Supprimer la catégorie vide</button><div id="delmsg"></div></div></div><script>const $=i=>document.getElementById(i),E=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));function msg(id,text,ok){$(id).innerHTML='<div class="msg '+(ok?'ok':'err')+'">'+E(text)+'</div>'}async function load(){try{let r=await fetch('/api/admin/categories-diagnostic?t='+Date.now(),{cache:'no-store'}),d=await r.json();if(!r.ok||!d.ok)throw Error(d.error||'Erreur');$('summary').innerHTML='<div class="card"><b>'+d.count+' catégories • '+d.productCount+' produits</b><br><span class="hint">'+(Object.keys(d.orphanProductCategories||{}).length?'Attention : catégorie orpheline détectée.':'Aucune catégorie orpheline détectée.')+'</span></div>';$('rows').innerHTML=d.categories.map(c=>'<tr><td><b>'+E(c.name)+'</b></td><td>'+c.products+'</td><td>'+c.activeProducts+'</td></tr>').join('')}catch(e){$('summary').innerHTML='<div class="msg err">'+E(e.message)+'</div>'}}async function post(url,body,id){try{let r=await fetch(url,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}),d=await r.json();if(!r.ok||!d.ok)throw Error(d.error||d.detail||'Erreur');msg(id,d.message||'Opération réussie',true);await load()}catch(e){msg(id,e.message,false)}}function addCat(){post('/api/admin/categories-add-test',{name:$('add').value},'addmsg')}function renameCat(){post('/api/admin/categories-rename-test',{old:$('old').value,new:$('new').value},'renmsg')}function deleteCat(){let n=$('del').value;if(!confirm('Supprimer « '+n+' » uniquement si cette catégorie est vide ?'))return;post('/api/admin/categories-delete-test',{name:n},'delmsg')}load();</script></body></html>''',content_type='text/html; charset=utf-8')
